import { LeaveStatus } from 'shared/types';

export interface LeaveRequest {
  id: string;
  employeeId: string;
  leavePolicyId: string;
  startDate: Date;
  endDate: Date;
  reason: string | undefined;
  status: LeaveStatus;
  approvedBy: string | null;
  approvedAt: Date | null;
  cancelledBy: string | null;
  cancelledAt: Date | null;
  createdAt: Date;
  updatedAt: Date;
}

export interface CreateLeaveRequestDto {
  employeeId: string;
  leavePolicyId: string;
  startDate: Date;
  endDate: Date;
  reason?: string;
}

export interface UpdateLeaveRequestDto {
  startDate?: Date;
  endDate?: Date;
  reason?: string;
  status?: LeaveStatus;
}

export interface LeaveRequestQueryParams {
  employeeId?: string;
  status?: LeaveStatus;
  leavePolicyId?: string;
  startDate?: Date;
  endDate?: Date;
}

import { PoolClient } from 'pg';
import { IBaseRepository, BaseRepository } from 'shared/base-repository';
import { LeaveRequest } from './leave-request.model';
import { LeaveStatus } from 'shared/types';

export interface ILeaveRequestRepository extends IBaseRepository<LeaveRequest> {
  findByEmployeeId(employeeId: string, client?: PoolClient): Promise<LeaveRequest[]>;
  findByStatus(status: LeaveStatus, client?: PoolClient): Promise<LeaveRequest[]>;
  findOverlapping(employeeId: string, startDate: Date, endDate: Date, excludeId?: string, client?: PoolClient): Promise<LeaveRequest[]>;
  findByDateRange(startDate: Date, endDate: Date, client?: PoolClient): Promise<LeaveRequest[]>;
  findPendingForManager(managerId: string, client?: PoolClient): Promise<LeaveRequest[]>;
}

export class LeaveRequestRepository extends BaseRepository<LeaveRequest> implements ILeaveRequestRepository {
  protected readonly tableName = 'leave_requests';

  async findByEmployeeId(employeeId: string, client?: PoolClient): Promise<LeaveRequest[]> {
    const executor = client ?? this.pool;
    const result = await executor.query(
      `SELECT * FROM ${this.tableName} WHERE employee_id = $1 ORDER BY created_at DESC`,
      [employeeId],
    );
    return result.rows;
  }

  async findByStatus(status: LeaveStatus, client?: PoolClient): Promise<LeaveRequest[]> {
    const executor = client ?? this.pool;
    const result = await executor.query(
      `SELECT * FROM ${this.tableName} WHERE status = $1 ORDER BY created_at DESC`,
      [status],
    );
    return result.rows;
  }

  async findOverlapping(employeeId: string, startDate: Date, endDate: Date, excludeId?: string, client?: PoolClient): Promise<LeaveRequest[]> {
    const executor = client ?? this.pool;
    const params: unknown[] = [employeeId, endDate, startDate];
    let sql = `SELECT * FROM ${this.tableName} WHERE employee_id = $1 AND start_date <= $2 AND end_date >= $3 AND status NOT IN ('REJECTED', 'CANCELLED')`;

    if (excludeId) {
      params.push(excludeId);
      sql += ` AND id != $${params.length}`;
    }

    sql += ' ORDER BY start_date ASC';
    const result = await executor.query(sql, params);
    return result.rows;
  }

  async findByDateRange(startDate: Date, endDate: Date, client?: PoolClient): Promise<LeaveRequest[]> {
    const executor = client ?? this.pool;
    const result = await executor.query(
      `SELECT * FROM ${this.tableName} WHERE start_date <= $1 AND end_date >= $2 ORDER BY start_date ASC`,
      [endDate, startDate],
    );
    return result.rows;
  }

  async findPendingForManager(managerId: string, client?: PoolClient): Promise<LeaveRequest[]> {
    const executor = client ?? this.pool;
    const result = await executor.query(
      `SELECT lr.* FROM ${this.tableName} lr
       INNER JOIN employees e ON lr.employee_id = e.id
       WHERE e.manager_id = $1 AND lr.status = 'SUBMITTED'
       ORDER BY lr.created_at ASC`,
      [managerId],
    );
    return result.rows;
  }
}

import {
  LeaveRequest,
  CreateLeaveRequestDto,
  UpdateLeaveRequestDto,
  LeaveRequestQueryParams,
} from './leave-request.model';
import { ILeaveRequestRepository } from './leave-request.repository';
import { IEmployeeService } from 'modules/employee';
import { ILeavePolicyService } from 'modules/leave-policy';
import { ILeaveBalanceService } from 'modules/balance';
import { LeaveStatus, LeaveType } from 'shared/types';
import { NotFoundError, ValidationError, ConflictError } from 'shared/error-types';

export interface ILeaveRequestService {
  create(dto: CreateLeaveRequestDto): Promise<LeaveRequest>;
  submit(id: string): Promise<LeaveRequest>;
  approve(id: string, approverId: string): Promise<LeaveRequest>;
  reject(id: string, approverId: string): Promise<LeaveRequest>;
  cancel(id: string, cancelledBy: string): Promise<LeaveRequest>;
  update(id: string, dto: UpdateLeaveRequestDto): Promise<LeaveRequest>;
  getById(id: string): Promise<LeaveRequest>;
  query(params: LeaveRequestQueryParams): Promise<LeaveRequest[]>;
  getEmployeeRequests(employeeId: string): Promise<LeaveRequest[]>;
}

export class LeaveRequestService implements ILeaveRequestService {
  constructor(
    private readonly leaveRequestRepository: ILeaveRequestRepository,
    private readonly employeeService: IEmployeeService,
    private readonly leavePolicyService: ILeavePolicyService,
    private readonly leaveBalanceService: ILeaveBalanceService,
  ) {}

  async create(dto: CreateLeaveRequestDto): Promise<LeaveRequest> {
    if (dto.endDate < dto.startDate) {
      throw new ValidationError('endDate must be on or after startDate');
    }

    const employee = await this.employeeService.getById(dto.employeeId);
    if (employee.employmentStatus !== 'ACTIVE') {
      throw new ValidationError('Employee is not active');
    }

    const policy = await this.leavePolicyService.getById(dto.leavePolicyId);
    if (!policy.isActive) {
      throw new ValidationError('Leave policy is not active');
    }

    const leaveRequest = await this.leaveRequestRepository.create({
      employeeId: dto.employeeId,
      leavePolicyId: dto.leavePolicyId,
      startDate: dto.startDate,
      endDate: dto.endDate,
      reason: dto.reason,
      status: LeaveStatus.DRAFT,
      approvedBy: null,
      approvedAt: null,
      cancelledBy: null,
      cancelledAt: null,
      createdAt: new Date(),
      updatedAt: new Date(),
    });

    return leaveRequest;
  }

  async submit(id: string): Promise<LeaveRequest> {
    const leaveRequest = await this.leaveRequestRepository.findById(id);
    if (!leaveRequest) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }

    if (leaveRequest.status !== LeaveStatus.DRAFT) {
      throw new ValidationError(
        `Cannot submit leave request with status ${leaveRequest.status}`,
      );
    }

    const employee = await this.employeeService.getById(leaveRequest.employeeId);
    if (employee.employmentStatus !== 'ACTIVE') {
      throw new ValidationError('Employee is not active');
    }

    const policy = await this.leavePolicyService.getById(leaveRequest.leavePolicyId);
    if (!policy.isActive) {
      throw new ValidationError('Leave policy is not active');
    }

    const isEmergency = policy.leaveType === LeaveType.EMERGENCY;

    if (!isEmergency && policy.minimumNoticeDays !== null && policy.minimumNoticeDays !== undefined) {
      const now = new Date();
      const noticeMs = leaveRequest.startDate.getTime() - now.getTime();
      const noticeDays = Math.floor(noticeMs / (1000 * 60 * 60 * 24));
      if (noticeDays < policy.minimumNoticeDays) {
        throw new ValidationError(
          `Leave request requires ${policy.minimumNoticeDays} days notice, but only ${noticeDays} days provided`,
        );
      }
    }

    const overlapping = await this.leaveRequestRepository.findOverlapping(
      leaveRequest.employeeId,
      leaveRequest.startDate,
      leaveRequest.endDate,
      leaveRequest.id,
    );

    if (overlapping.length > 0) {
      throw new ConflictError('Employee has overlapping leave requests');
    }

    const daysRequested = this.computeDays(leaveRequest.startDate, leaveRequest.endDate);
    const fiscalYear = leaveRequest.startDate.getFullYear();

    const remainingDays = await this.leaveBalanceService.getRemainingDays(
      leaveRequest.employeeId,
      leaveRequest.leavePolicyId,
      fiscalYear,
    );

    if (remainingDays < daysRequested) {
      throw new ValidationError(
        `Insufficient leave balance: requested ${daysRequested} days but only ${remainingDays} remaining`,
      );
    }

    const updated = await this.leaveRequestRepository.update(id, {
      status: LeaveStatus.SUBMITTED,
      updatedAt: new Date(),
    });

    if (!updated) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }

    return updated;
  }

  async approve(id: string, approverId: string): Promise<LeaveRequest> {
    const leaveRequest = await this.leaveRequestRepository.findById(id);
    if (!leaveRequest) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }

    if (leaveRequest.status !== LeaveStatus.SUBMITTED) {
      throw new ValidationError(
        `Cannot approve leave request with status ${leaveRequest.status}`,
      );
    }

    const fiscalYear = leaveRequest.startDate.getFullYear();

    await this.leaveBalanceService.deductDays(
      leaveRequest.employeeId,
      leaveRequest.leavePolicyId,
      fiscalYear,
      leaveRequest.startDate,
      leaveRequest.endDate,
    );

    const updated = await this.leaveRequestRepository.update(id, {
      status: LeaveStatus.APPROVED,
      approvedBy: approverId,
      approvedAt: new Date(),
      updatedAt: new Date(),
    });

    if (!updated) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }

    return updated;
  }

  async reject(id: string, approverId: string): Promise<LeaveRequest> {
    const leaveRequest = await this.leaveRequestRepository.findById(id);
    if (!leaveRequest) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }

    if (leaveRequest.status !== LeaveStatus.SUBMITTED) {
      throw new ValidationError(
        `Cannot reject leave request with status ${leaveRequest.status}`,
      );
    }

    const updated = await this.leaveRequestRepository.update(id, {
      status: LeaveStatus.REJECTED,
      approvedBy: approverId,
      approvedAt: new Date(),
      updatedAt: new Date(),
    });

    if (!updated) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }

    return updated;
  }

  async cancel(id: string, cancelledBy: string): Promise<LeaveRequest> {
    const leaveRequest = await this.leaveRequestRepository.findById(id);
    if (!leaveRequest) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }

    if (
      leaveRequest.status !== LeaveStatus.APPROVED &&
      leaveRequest.status !== LeaveStatus.SUBMITTED
    ) {
      throw new ValidationError(
        `Cannot cancel leave request with status ${leaveRequest.status}`,
      );
    }

    if (leaveRequest.status === LeaveStatus.APPROVED) {
      const daysRequested = this.computeDays(leaveRequest.startDate, leaveRequest.endDate);
      const fiscalYear = leaveRequest.startDate.getFullYear();

      await this.leaveBalanceService.restoreDays(
        leaveRequest.employeeId,
        leaveRequest.leavePolicyId,
        fiscalYear,
        daysRequested,
      );
    }

    const updated = await this.leaveRequestRepository.update(id, {
      status: LeaveStatus.CANCELLED,
      cancelledBy: cancelledBy,
      cancelledAt: new Date(),
      updatedAt: new Date(),
    });

    if (!updated) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }

    return updated;
  }

  async update(id: string, dto: UpdateLeaveRequestDto): Promise<LeaveRequest> {
    const leaveRequest = await this.leaveRequestRepository.findById(id);
    if (!leaveRequest) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }

    if (leaveRequest.status !== LeaveStatus.DRAFT) {
      throw new ValidationError(
        `Cannot update leave request with status ${leaveRequest.status}`,
      );
    }

    if (dto.startDate && dto.endDate && dto.endDate < dto.startDate) {
      throw new ValidationError('endDate must be on or after startDate');
    }

    const updateData: Partial<LeaveRequest> = {
      ...dto,
      updatedAt: new Date(),
    };

    const updated = await this.leaveRequestRepository.update(id, updateData);

    if (!updated) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }

    return updated;
  }

  async getById(id: string): Promise<LeaveRequest> {
    const leaveRequest = await this.leaveRequestRepository.findById(id);
    if (!leaveRequest) {
      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
    }
    return leaveRequest;
  }

  async query(params: LeaveRequestQueryParams): Promise<LeaveRequest[]> {
    if (params.employeeId) {
      return this.leaveRequestRepository.findByEmployeeId(params.employeeId);
    }

    if (params.status) {
      return this.leaveRequestRepository.findByStatus(params.status);
    }

    if (params.startDate && params.endDate) {
      return this.leaveRequestRepository.findByDateRange(params.startDate, params.endDate);
    }

    return this.leaveRequestRepository.findAll();
  }

  async getEmployeeRequests(employeeId: string): Promise<LeaveRequest[]> {
    return this.leaveRequestRepository.findByEmployeeId(employeeId);
  }

  private computeDays(startDate: Date, endDate: Date): number {
    const startMs = startDate.getTime();
    const endMs = endDate.getTime();
    const diffMs = endMs - startMs;
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    return diffDays + 1;
  }
}

import { FastifyRequest, FastifyReply } from 'fastify';
import { z } from 'zod';
import { ILeaveRequestService } from './leave-request.service';
import { LeaveStatus } from 'shared/types';
import { NotFoundError, ValidationError, ConflictError } from 'shared/error-types';

const createSchema = z.object({
  employeeId: z.string().min(1),
  leavePolicyId: z.string().min(1),
  startDate: z.string().refine((val) => !isNaN(Date.parse(val)), {
    message: 'startDate must be a valid date string',
  }),
  endDate: z.string().refine((val) => !isNaN(Date.parse(val)), {
    message: 'endDate must be a valid date string',
  }),
  reason: z.string().optional(),
});

const updateSchema = z.object({
  startDate: z
    .string()
    .refine((val) => !isNaN(Date.parse(val)), {
      message: 'startDate must be a valid date string',
    })
    .optional(),
  endDate: z
    .string()
    .refine((val) => !isNaN(Date.parse(val)), {
      message: 'endDate must be a valid date string',
    })
    .optional(),
  reason: z.string().optional(),
});

const idParamsSchema = z.object({
  id: z.string().min(1),
});

const approveRejectBodySchema = z.object({
  approverId: z.string().min(1),
});

const cancelBodySchema = z.object({
  cancelledBy: z.string().min(1),
});

const querySchema = z.object({
  employeeId: z.string().optional(),
  status: z.nativeEnum(LeaveStatus).optional(),
  leavePolicyId: z.string().optional(),
  startDate: z
    .string()
    .refine((val) => !isNaN(Date.parse(val)), {
      message: 'startDate must be a valid date string',
    })
    .optional(),
  endDate: z
    .string()
    .refine((val) => !isNaN(Date.parse(val)), {
      message: 'endDate must be a valid date string',
    })
    .optional(),
});

export class LeaveRequestController {
  constructor(private readonly leaveRequestService: ILeaveRequestService) {}

  createLeaveRequest = async (
    request: FastifyRequest,
    reply: FastifyReply,
  ): Promise<void> => {
    const parsed = createSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: 'Validation Error',
        details: parsed.error.issues,
      });
    }

    const dto = {
      employeeId: parsed.data.employeeId,
      leavePolicyId: parsed.data.leavePolicyId,
      startDate: new Date(parsed.data.startDate),
      endDate: new Date(parsed.data.endDate),
      reason: parsed.data.reason,
    };

    try {
      const result = await this.leaveRequestService.create(dto);
      return reply.status(201).send(result);
    } catch (err: unknown) {
      if (err instanceof NotFoundError) {
        return reply.status(404).send({ error: err.message, code: 'NOT_FOUND', statusCode: 404 });
      }
      if (err instanceof ValidationError) {
        return reply.status(400).send({ error: err.message, code: 'VALIDATION_ERROR', statusCode: 400 });
      }
      if (err instanceof ConflictError) {
        return reply.status(409).send({ error: err.message, code: 'CONFLICT', statusCode: 409 });
      }
      throw err;
    }
  };

  submitLeaveRequest = async (
    request: FastifyRequest,
    reply: FastifyReply,
  ): Promise<void> => {
    const paramsParsed = idParamsSchema.safeParse(request.params);
    if (!paramsParsed.success) {
      return reply.status(400).send({
        error: 'Validation Error',
        details: paramsParsed.error.issues,
      });
    }

    try {
      const result = await this.leaveRequestService.submit(paramsParsed.data.id);
      return reply.status(200).send(result);
    } catch (err: unknown) {
      if (err instanceof NotFoundError) {
        return reply.status(404).send({ error: err.message, code: 'NOT_FOUND', statusCode: 404 });
      }
      if (err instanceof ValidationError) {
        return reply.status(400).send({ error: err.message, code: 'VALIDATION_ERROR', statusCode: 400 });
      }
      if (err instanceof ConflictError) {
        return reply.status(409).send({ error: err.message, code: 'CONFLICT', statusCode: 409 });
      }
      throw err;
    }
  };

  approveLeaveRequest = async (
    request: FastifyRequest,
    reply: FastifyReply,
  ): Promise<void> => {
    const paramsParsed = idParamsSchema.safeParse(request.params);
    if (!paramsParsed.success) {
      return reply.status(400).send({
        error: 'Validation Error',
        details: paramsParsed.error.issues,
      });
    }

    const bodyParsed = approveRejectBodySchema.safeParse(request.body);
    if (!bodyParsed.success) {
      return reply.status(400).send({
        error: 'Validation Error',
        details: bodyParsed.error.issues,
      });
    }

    try {
      const result = await this.leaveRequestService.approve(
        paramsParsed.data.id,
        bodyParsed.data.approverId,
      );
      return reply.status(200).send(result);
    } catch (err: unknown) {
      if (err instanceof NotFoundError) {
        return reply.status(404).send({ error: err.message, code: 'NOT_FOUND', statusCode: 404 });
      }
      if (err instanceof ValidationError) {
        return reply.status(400).send({ error: err.message, code: 'VALIDATION_ERROR', statusCode: 400 });
      }
      if (err instanceof ConflictError) {
        return reply.status(409).send({ error: err.message, code: 'CONFLICT', statusCode: 409 });
      }
      throw err;
    }
  };

  rejectLeaveRequest = async (
    request: FastifyRequest,
    reply: FastifyReply,
  ): Promise<void> => {
    const paramsParsed = idParamsSchema.safeParse(request.params);
    if (!paramsParsed.success) {
      return reply.status(400).send({
        error: 'Validation Error',
        details: paramsParsed.error.issues,
      });
    }

    const bodyParsed = approveRejectBodySchema.safeParse(request.body);
    if (!bodyParsed.success) {
      return reply.status(400).send({
        error: 'Validation Error',
        details: bodyParsed.error.issues,
      });
    }

    try {
      const result = await this.leaveRequestService.reject(
        paramsParsed.data.id,
        bodyParsed.data.approverId,
      );
      return reply.status(200).send(result);
